enum Potion
{
    Small,
    Large,
}

struct Flask
{
    public Potion Kind;
    public int Doses;
}

static class Alchemy
{
    public static int Doses(Flask[] flasks)
    {
        int doses = 0;
        foreach (Flask flask in flasks)
        {
            doses += flask.Doses;
        }

        return doses;
    }
}

class Shelf
{
    public int Count()
    {
        Flask a = new Flask { Kind = Potion.Small, Doses = 2 };
        Flask b = a;
        b.Doses = 9;
        return Alchemy.Doses([a, b]);
    }
}
